const state={rooms:2,baths:1,property:'apartment',type:'standard',lang:window.getGoCleanLanguage?.()||'uz'};
const prices={apartment:{base:99000,room:60000,bath:30000},house:{base:149000,room:72000,bath:35000},office:{base:199000,room:45000,bath:40000}};
const multipliers={standard:1,general:1.8,repair:2.65};
const fmt=n=>new Intl.NumberFormat(state.lang==='ru'?'ru-RU':'uz-UZ').format(Math.round(n/1000)*1000)+(state.lang==='ru'?' сум':' so‘m');
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function calculate(){const p=prices[state.property];const total=(p.base+state.rooms*p.room+state.baths*p.bath)*multipliers[state.type];$('#roomsValue').textContent=state.rooms;$('#bathsValue').textContent=state.baths;$('#totalPrice').textContent=fmt(total);const orderText=state.lang==='ru'?'Заказать уборку':'Buyurtma berish';$('#orderLabel').textContent=`${orderText} — ${fmt(total)}`;return total}
$$('[data-action]').forEach(btn=>btn.addEventListener('click',()=>{const a=btn.dataset.action;if(a==='room-plus')state.rooms=Math.min(20,state.rooms+1);if(a==='room-minus')state.rooms=Math.max(1,state.rooms-1);if(a==='bath-plus')state.baths=Math.min(10,state.baths+1);if(a==='bath-minus')state.baths=Math.max(1,state.baths-1);calculate()}));
$$('[data-property]').forEach(btn=>btn.addEventListener('click',()=>{if(btn.dataset.property==='office'){location.href='office-cleaning.html';return}$$('[data-property]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');state.property=btn.dataset.property;calculate()}));
$$('[data-type]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-type]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');state.type=btn.dataset.type;calculate()}));
const modal=$('#orderModal');$('#orderButton').addEventListener('click',()=>{const service={standard:'general-cleaning',general:'general-cleaning',repair:'after-renovation'}[state.type];const object={apartment:'apartment',house:'cottage',office:'office'}[state.property];location.href=`booking.html?service=${service}&object=${object}&rooms=${state.rooms}&baths=${state.baths}`});$('.modal-close')?.addEventListener('click',()=>modal.close());
$('#calculatorCallback')?.addEventListener('click',()=>modal.showModal());
modal?.addEventListener('click',e=>{if(e.target===modal)modal.close()});
async function submitCallback(e){e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));try{await window.GoCleanLeads.send('callback',{name:data.customerName,phone:data.customerPhone,property:state.property,cleaningType:state.type,rooms:String(state.rooms),bathrooms:String(state.baths),total:fmt(calculate())},form);if(modal.open)modal.close();form.reset();window.GoCleanLeads.showToast(state.lang==='ru'?'Спасибо! Мы скоро свяжемся с вами.':'Rahmat! Tez orada siz bilan bog‘lanamiz.')}catch(error){window.GoCleanLeads.showToast(error.message||window.GoCleanLeads.errorText(),true)}}
$('#orderForm')?.addEventListener('submit',submitCallback);$('#businessForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));try{await window.GoCleanLeads.send('consultation',{name:data.name,phone:data.phone},form);form.reset();window.GoCleanLeads.showToast(state.lang==='ru'?'Заявка принята. Менеджер скоро свяжется с вами.':'Arizangiz qabul qilindi. Menejer tez orada bog‘lanadi.')}catch(error){window.GoCleanLeads.showToast(error.message||window.GoCleanLeads.errorText(),true)}});
